const rows = $input.all().map(i => i.json);
return [{ json: {
  text: `🧭 Outcome check: ${rows.length} problem(s)\n` + rows.map(r => '• ' + r.detail).join('\n'),
  checks: rows.map(r => r.check_name)
} }];

